 89→// initConfig loads and merges configuration from user-global and per-project
 90→// directories, applies CLI flag overrides, and returns the resolved config,
 91→// routing config, and plugin configs.
 92→func initConfig() (*config.Config, *router.Config, map[string]mcp.PluginConfig, error) {
 93→	workDir, err := os.Getwd()
 94→	if err != nil {
 95→		return nil, nil, nil, fmt.Errorf("getwd: %w", err)
 96→	}
 97→	cfg, err := config.Load(workDir)
 98→	if err != nil {
 99→		return nil, nil, nil, err
100→	}
101→
102→	// Load and merge routing configs (user-global base, per-project overlay)
103→	var routerCfg *router.Config
104→	routingPaths := cfg.RoutingPaths()
105→	if len(routingPaths) == 0 {
106→		routerCfg = &router.Config{Phases: make(map[tool.Phase]string)}
107→	} else {
108→		base, err := router.LoadConfig(routingPaths[0])
109→		if err != nil {
110→			fmt.Fprintf(os.Stderr, "skaffen: warning: routing config: %v\n", err)
111→			routerCfg = &router.Config{Phases: make(map[tool.Phase]string)}
112→		} else {
113→			routerCfg = base
114→			if len(routingPaths) > 1 {
115→				project, err := router.LoadConfig(routingPaths[1])
116→				if err != nil {
117→					fmt.Fprintf(os.Stderr, "skaffen: warning: project routing config: %v\n", err)
118→				} else {
119→					routerCfg = router.MergeConfig(base, project)
120→				}
121→			}
122→		}
123→	}
124→
125→	// CLI --budget flag overrides config file budget
126→	if *flagBudget > 0 {
127→		routerCfg.Budget = &router.BudgetConfig{
128→			MaxTokens: *flagBudget,
129→			Mode:      "graceful",
130→			DegradeAt: 0.8,
131→		}
132→	}
133→
134→	// CLI --model flag: set as override for all phases
135→	if *flagModel != "" {
136→		if routerCfg.Phases == nil {
137→			routerCfg.Phases = make(map[tool.Phase]string)
138→		}
139→		for _, ph := range []tool.Phase{tool.PhaseBrainstorm, tool.PhasePlan, tool.PhaseBuild, tool.PhaseReview, tool.PhaseShip} {
140→			routerCfg.Phases[ph] = *flagModel
141→		}
142→	}
143→
144→	// Load and merge plugin configs
145→	var pluginsCfg map[string]mcp.PluginConfig
146→	if *flagPlugins != "" {
147→		// CLI flag overrides entire config hierarchy
148→		pluginsCfg, err = mcp.LoadConfig(*flagPlugins)
149→		if err != nil {
150→			fmt.Fprintf(os.Stderr, "skaffen: warning: plugins config: %v\n", err)
151→			pluginsCfg = make(map[string]mcp.PluginConfig)
152→		}
153→	} else {
154→		pluginPaths := cfg.PluginPaths()
155→		for _, p := range pluginPaths {
156→			pcfg, err := mcp.LoadConfig(p)
157→			if err != nil {
158→				fmt.Fprintf(os.Stderr, "skaffen: warning: plugins config %s: %v\n", p, err)
159→				continue
160→			}
161→			if pluginsCfg == nil {
162→				pluginsCfg = pcfg
163→			} else {
164→				pluginsCfg = mcp.MergePluginConfigs(pluginsCfg, pcfg)
165→			}
166→		}
167→		if pluginsCfg == nil {
168→			pluginsCfg = make(map[string]mcp.PluginConfig)
169→		}
170→	}
171→
172→	return cfg, routerCfg, pluginsCfg, nil
173→}
