175→func runPrint() error {
176→	// Context with signal handling
177→	ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
178→	defer cancel()
179→
180→	ic := checkIntercore()
181→
182→	// Validate phase
183→	phase := tool.Phase(*flagPhase)
184→	switch phase {
185→	case tool.PhaseBrainstorm, tool.PhasePlan, tool.PhaseBuild, tool.PhaseReview, tool.PhaseShip:
186→		// valid
187→	default:
188→		return fmt.Errorf("invalid phase %q (must be brainstorm, plan, build, review, or ship)", *flagPhase)
189→	}
190→
191→	// Read prompt from -p flag or stdin
192→	prompt := *flagPrompt
193→	if prompt == "" {
194→		data, err := io.ReadAll(os.Stdin)
195→		if err != nil {
196→			return fmt.Errorf("reading stdin: %w", err)
197→		}
198→		prompt = strings.TrimSpace(string(data))
199→	}
200→	if prompt == "" {
201→		return fmt.Errorf("no prompt provided (use -p or pipe to stdin)")
202→	}
203→
204→	// Resolve provider: auto-detect if not specified
205→	providerName := *flagProvider
206→	if providerName == "" {
207→		if os.Getenv("ANTHROPIC_API_KEY") != "" {
208→			providerName = "anthropic"
209→		} else {
210→			providerName = "claude-code" // default — works with Claude Max OAuth
211→		}
212→	}
213→
214→	pcfg := provider.ProviderConfig{}
215→	if providerName == "anthropic" {
216→		pcfg.APIKey = os.Getenv("ANTHROPIC_API_KEY")
217→		if pcfg.APIKey == "" {
218→			return fmt.Errorf("ANTHROPIC_API_KEY not set (omit --provider to use Claude Max via claude-code)")
219→		}
220→	}
221→
222→	p, err := provider.New(providerName, pcfg)
223→	if err != nil {
224→		return fmt.Errorf("provider: %w", err)
225→	}
226→
227→	// Initialize tool registry
228→	reg := tool.NewRegistry()
229→	tool.RegisterBuiltins(reg)
230→
231→	// Load config (user-global + per-project + CLI overrides)
232→	cfg, routerCfg, pluginsCfg, err := initConfig()
233→	if err != nil {
234→		return fmt.Errorf("config: %w", err)
235→	}
236→
237→	// Load MCP plugins
238→	mcpMgr := loadMCPPluginsFromConfig(ctx, reg, pluginsCfg)
239→	if mcpMgr != nil {
240→		defer mcpMgr.Shutdown()
241→	}
242→
243→	// Session ID — used for both session persistence and evidence
244→	sessionID := *flagSession
245→	if sessionID == "" {
246→		sessionID = fmt.Sprintf("skaffen-%d", os.Getpid())
247→	}
248→
249→	modelRouter := router.NewWithIC(routerCfg, ic, sessionID)
250→
251→	// Configure agent
252→	opts := []agent.Option{
253→		agent.WithMaxTurns(*flagMaxTurns),
254→		agent.WithStartPhase(phase),
255→		agent.WithRouter(modelRouter),
256→	}
257→
258→	// Build system prompt from context files + --system flag
259→	systemPrompt := buildSystemPrompt(cfg.WorkDir(), *flagSystem)
260→
261→	if *flagSession != "" {
262→		sess := session.New(*flagSession, cfg.SessionDir(), systemPrompt, 20)
263→		if err := sess.Load(); err != nil {
264→			fmt.Fprintf(os.Stderr, "skaffen: warning: load session: %v\n", err)
265→		}
266→		opts = append(opts, agent.WithSession(sess))
267→	} else if systemPrompt != "" {
268→		opts = append(opts, agent.WithSession(&agent.NoOpSession{Prompt: systemPrompt}))
269→	}
270→
271→	// Evidence emission — always enabled
272→	emitter := evidence.New(cfg.EvidenceDir(), sessionID)
273→	opts = append(opts, agent.WithEmitter(emitter), agent.WithSessionID(sessionID))
274→
275→	// Lifecycle hooks — only gate in headless mode (no trust evaluator)
276→	if hookExec := loadHooks(cfg, sessionID, string(phase)); hookExec != nil {
277→		hookExec.SessionStart(ctx, "print")
278→		opts = append(opts, agent.WithHooks(hookExec))
279→	}
280→
281→	a := agent.New(p, reg, opts...)
282→
283→	// Run agent loop
284→	result, err := a.Run(ctx, prompt)
285→	if err != nil {
286→		return err
287→	}
288→
289→	// Print response to stdout
290→	fmt.Print(result.Response)
291→
292→	// Print usage to stderr
293→	fmt.Fprintf(os.Stderr, "\n[%d turns, %d in / %d out tokens]\n",
294→		result.Turns, result.Usage.InputTokens, result.Usage.OutputTokens)
295→
296→	return nil
297→}
