299→func runTUI() error {
300→	ic := checkIntercore()
301→
302→	// Resolve provider (same logic as runPrint)
303→	providerName := *flagProvider
304→	if providerName == "" {
305→		if os.Getenv("ANTHROPIC_API_KEY") != "" {
306→			providerName = "anthropic"
307→		} else {
308→			providerName = "claude-code"
309→		}
310→	}
311→
312→	pcfg := provider.ProviderConfig{}
313→	if providerName == "anthropic" {
314→		pcfg.APIKey = os.Getenv("ANTHROPIC_API_KEY")
315→		if pcfg.APIKey == "" {
316→			return fmt.Errorf("ANTHROPIC_API_KEY not set")
317→		}
318→	}
319→
320→	p, err := provider.New(providerName, pcfg)
321→	if err != nil {
322→		return fmt.Errorf("provider: %w", err)
323→	}
324→
325→	// Tool registry
326→	reg := tool.NewRegistry()
327→	tool.RegisterBuiltins(reg)
328→
329→	// Load config (user-global + per-project + CLI overrides)
330→	cfg, routerCfg, pluginsCfg, err := initConfig()
331→	if err != nil {
332→		return fmt.Errorf("config: %w", err)
333→	}
334→
335→	// Load MCP plugins (use timeout context since TUI manages its own context)
336→	mcpCtx, mcpCancel := context.WithTimeout(context.Background(), 30*time.Second)
337→	mcpMgr := loadMCPPluginsFromConfig(mcpCtx, reg, pluginsCfg)
338→	mcpCancel()
339→	if mcpMgr != nil {
340→		defer mcpMgr.Shutdown()
341→	}
342→
343→	// Session
344→	sessionID := *flagSession
345→	if sessionID == "" {
346→		sessionID = fmt.Sprintf("skaffen-%d", os.Getpid())
347→	}
348→
349→	modelRouter := router.NewWithIC(routerCfg, ic, sessionID)
350→
351→	phase := tool.Phase(*flagPhase)
352→
353→	opts := []agent.Option{
354→		agent.WithMaxTurns(*flagMaxTurns),
355→		agent.WithStartPhase(phase),
356→		agent.WithRouter(modelRouter),
357→	}
358→
359→	// Working directory + context files
360→	systemPrompt := buildSystemPrompt(cfg.WorkDir(), *flagSystem)
361→
362→	var tuiSession *session.JSONLSession
363→	if *flagSession != "" {
364→		tuiSession = session.New(*flagSession, cfg.SessionDir(), systemPrompt, 20)
365→		if err := tuiSession.Load(); err != nil {
366→			fmt.Fprintf(os.Stderr, "skaffen: warning: load session: %v\n", err)
367→		}
368→		opts = append(opts, agent.WithSession(tuiSession))
369→	} else if systemPrompt != "" {
370→		opts = append(opts, agent.WithSession(&agent.NoOpSession{Prompt: systemPrompt}))
371→	}
372→
373→	// Evidence
374→	emitter := evidence.New(cfg.EvidenceDir(), sessionID)
375→	opts = append(opts, agent.WithEmitter(emitter), agent.WithSessionID(sessionID))
376→
377→	// Trust evaluator
378→	trustEval := trust.NewEvaluator(nil)
379→
380→	// Lifecycle hooks — pre-filter before trust evaluator
381→	if hookExec := loadHooks(cfg, sessionID, string(phase)); hookExec != nil {
382→		hookExec.SessionStart(context.Background(), "tui")
383→		opts = append(opts, agent.WithHooks(hookExec))
384→	}
385→
386→	// Load custom slash commands from disk
387→	customCmds := command.LoadAll(cfg.CommandDirs()...)
388→
389→	// Create agent
390→	a := agent.New(p, reg, opts...)
391→
392→	// Run TUI
393→	return tui.Run(tui.Config{
394→		Agent:          a,
395→		Trust:          trustEval,
396→		Session:        tuiSession,
397→		SessionID:      sessionID,
398→		Verbose:        false,
399→		WorkDir:        cfg.WorkDir(),
400→		SkaffenVer:     skaffenVersion(),
401→		MasaqVer:       masaqVersion(),
402→		CustomCommands: customCmds,
403→	})
404→}
