406→// checkIntercore detects the ic (Intercore CLI) for evidence and routing integration.
407→// Returns nil client (not error) if ic is unavailable — Skaffen degrades gracefully.
408→func checkIntercore() *router.ICClient {
409→	ic, err := router.NewICClient()
410→	if err != nil {
411→		fmt.Fprintf(os.Stderr, "skaffen: warning: intercore unavailable: %v\n", err)
412→		return nil
413→	}
414→	if err := ic.Health(); err != nil {
415→		fmt.Fprintf(os.Stderr, "skaffen: warning: intercore unhealthy: %v\n", err)
416→		return nil
417→	}
418→	return ic
419→}
