421→// loadMCPPluginsFromConfig loads pre-resolved plugin configs into the registry.
422→// Returns the manager (may be nil if no plugins configured) — caller must defer Shutdown().
423→func loadMCPPluginsFromConfig(ctx context.Context, reg *tool.Registry, pluginsCfg map[string]mcp.PluginConfig) *mcp.Manager {
424→	if len(pluginsCfg) == 0 {
425→		return nil
426→	}
427→	mgr := mcp.NewManager(pluginsCfg, reg)
428→	if err := mgr.LoadAll(ctx); err != nil {
429→		fmt.Fprintf(os.Stderr, "skaffen: warning: MCP plugins: %v\n", err)
430→	}
431→	fmt.Fprintf(os.Stderr, "skaffen: loaded %d MCP plugin(s), %d tool(s)\n",
432→		mgr.PluginCount(), mgr.ToolCount())
433→	return mgr
434→}
