436→// loadHooks loads and merges hook configs (user-global + per-project),
437→// returning an Executor ready for use. Returns nil if no hooks are configured.
438→func loadHooks(cfg *config.Config, sessionID, phase string) *hooks.Executor {
439→	hookPaths := cfg.HookPaths()
440→	if len(hookPaths) == 0 {
441→		return nil
442→	}
443→
444→	base, err := hooks.LoadConfig(hookPaths[0])
445→	if err != nil {
446→		log.Printf("skaffen: warning: hook config: %v", err)
447→		return nil
448→	}
449→	merged := base
450→	if len(hookPaths) > 1 {
451→		project, err := hooks.LoadConfig(hookPaths[1])
452→		if err != nil {
453→			log.Printf("skaffen: warning: project hook config: %v", err)
454→		} else {
455→			merged = hooks.MergeConfig(base, project)
456→		}
457→	}
458→
459→	workDir, _ := os.Getwd()
460→	return hooks.NewExecutor(merged, sessionID, workDir, phase)
461→}
