463→// setupTheme configures the Masaq theme and color mode from CLI flags.
464→// Falls back to DetectMode() for color mode, TokyoNight for theme.
465→func setupTheme() {
466→	// Color mode: CLI flag > env var > terminal detection
467→	if *flagColorMode != "" {
468→		switch strings.ToLower(*flagColorMode) {
469→		case "light":
470→			theme.SetMode(theme.Light)
471→		default:
472→			theme.SetMode(theme.Dark)
473→		}
474→	} else {
475→		theme.SetMode(theme.DetectMode())
476→	}
477→
478→	// Theme selection
479→	if *flagTheme != "" {
480→		if t, ok := theme.ThemeByName(*flagTheme); ok {
481→			theme.SetCurrent(t)
482→		} else {
