// --system flag. Context files are loaded outermost-first (home → project).
func buildSystemPrompt(workDir, explicit string) string {
	ctx := contextfiles.Load(workDir)
	switch {
	case ctx != "" && explicit != "":
		return ctx + "\n\n---\n\n" + explicit
	case ctx != "":
		return ctx
	default:
		return explicit
	}
}

