	sb := newStatusBar(120)
	updateStatusSlots(&sb, "build", "opus", 0.0, 0, 0, false)
	view := sb.View()
	if !strings.Contains(view, "opus") {
		t.Fatal("status bar should contain model name")
	}
}

func TestStatusBarCostFormatting(t *testing.T) {
