 56→	r.tools[t.Name()] = t
 57→	// Ensure dynamically registered tools are available in build phase
 58→	if r.gates[PhaseBuild] == nil {
 59→		r.gates[PhaseBuild] = make(map[string]bool)
 60→	}
 61→	r.gates[PhaseBuild][t.Name()] = true
 62→}
