 64→// RegisterForPhases adds a tool to the registry, gated to specific phases.
 65→// If phases is nil or empty, defaults to build-only (same as Register).
 66→func (r *Registry) RegisterForPhases(t Tool, phases []Phase) {
 67→	r.tools[t.Name()] = t
 68→	if len(phases) == 0 {
 69→		phases = []Phase{PhaseBuild}
 70→	}
