119→	if !allowed[name] {
120→		return ToolResult{
121→			Content: fmt.Sprintf("tool %q not available in phase %q", name, phase),
122→			IsError: true,
123→		}
124→	}
125→
126→	t, ok := r.tools[name]
127→	if !ok {
128→		return ToolResult{
129→			Content: fmt.Sprintf("unknown tool %q", name),
130→			IsError: true,
131→		}
132→	}
133→
134→	return t.Execute(ctx, params)
135→}
