100→func (m *appModel) executeCommand(cmd *Command) CommandResult {
101→	switch cmd.Name {
102→	case "help":
103→		return CommandResult{Message: formatHelpWithCustom(m.customCmds)}
104→
105→	case "quit":
106→		return CommandResult{Message: "Goodbye!", Quit: true}
107→
108→	case "clear":
