125→
126→	case "status":
127→		return m.execStatus()
128→
129→	case "phase":
130→		if m.agent == nil {
131→			return CommandResult{Message: fmt.Sprintf("Phase: %s (no agent)", m.phase)}
132→		}
133→		return CommandResult{Message: fmt.Sprintf("Phase: %s", m.agent.CurrentPhase())}
134→
135→	case "advance":
136→		if m.agent == nil {
137→			return CommandResult{Message: "No agent configured.", IsError: true}
138→		}
139→		old := string(m.agent.CurrentPhase())
140→		if err := m.agent.AdvancePhase(); err != nil {
141→			return CommandResult{
142→				Message: fmt.Sprintf("Cannot advance: %v", err),
143→				IsError: true,
144→			}
145→		}
146→		newPhase := string(m.agent.CurrentPhase())
147→		m.phase = newPhase
148→		return CommandResult{
149→			Message: PhaseTransition(old, newPhase),
150→		}
151→
152→	case "settings":
153→		return m.execSettings(cmd.Args)
154→
155→	case "theme":
156→		if len(cmd.Args) == 0 {
157→			return m.execSettings([]string{"theme"})
158→		}
159→		return m.execSettings([]string{"theme", cmd.Args[0]})
160→
161→	case "diff":
