188→// execCustomCommand dispatches a disk-based custom command.
189→func (m *appModel) execCustomCommand(def command.Def, args []string) CommandResult {
190→	switch def.Type {
191→	case command.TypeTemplate:
192→		// Template commands inject text as a user prompt.
193→		// The caller (Update) handles submitting the returned message as input.
194→		return CommandResult{Message: def.Template}
195→	case command.TypeScript:
196→		// Script commands run via shell with a timeout.
197→		ctx, cancel := context.WithTimeout(context.Background(), shellTimeout)
198→		defer cancel()
199→
200→		cmd := exec.CommandContext(ctx, "bash", "-c", def.Script)
201→		cmd.Dir = m.workDir
202→		out, err := cmd.CombinedOutput()
203→
204→		output := string(out)
205→		if len(output) > shellMaxOutput {
206→			output = output[:shellMaxOutput] + "\n... (truncated)"
207→		}
208→		if ctx.Err() == context.DeadlineExceeded {
209→			return CommandResult{
210→				Message: fmt.Sprintf("/%s timed out after %s:\n%s", def.Name, shellTimeout, output),
211→				IsError: true,
212→			}
213→		}
214→		if err != nil {
215→			return CommandResult{
216→				Message: fmt.Sprintf("/%s failed: %v\n%s", def.Name, err, output),
217→				IsError: true,
218→			}
219→		}
220→		if output == "" {
221→			return CommandResult{Message: fmt.Sprintf("/%s completed (no output).", def.Name)}
222→		}
223→		return CommandResult{Message: output}
224→	default:
225→		return CommandResult{
226→			Message: fmt.Sprintf("Unknown command type %q for /%s", def.Type, def.Name),
227→			IsError: true,
228→		}
