389→func (m *appModel) execListSessions() CommandResult {
390→	sessDir := filepath.Join(os.Getenv("HOME"), ".skaffen", "sessions")
391→	sessions, err := session.ListSessions(sessDir)
392→	if err != nil {
393→		return CommandResult{Message: fmt.Sprintf("Error listing sessions: %v", err), IsError: true}
394→	}
395→	if len(sessions) == 0 {
396→		return CommandResult{Message: "No saved sessions."}
397→	}
398→	var b strings.Builder
399→	b.WriteString("Saved sessions:\n")
400→	limit := 10
401→	if len(sessions) < limit {
402→		limit = len(sessions)
403→	}
404→	for _, si := range sessions[:limit] {
405→		b.WriteString(fmt.Sprintf("  %s — %s\n", si.ID, session.FormatSessionEntry(si)))
406→	}
407→	if len(sessions) > 10 {
408→		b.WriteString(fmt.Sprintf("  ... and %d more\n", len(sessions)-10))
409→	}
410→	b.WriteString("\nResume with: skaffen -r <session-id>")
411→	return CommandResult{Message: b.String()}
412→}
413→
414→const compactKeepRecent = 4 // keep last 4 messages (2 turns) after compaction
415→
416→func (m *appModel) execCompact() CommandResult {
417→	if m.session == nil {
418→		return CommandResult{Message: "No session available for compaction.", IsError: true}
419→	}
420→	beforeCount := m.session.MessageCount()
421→	if beforeCount <= compactKeepRecent+1 {
422→		return CommandResult{Message: fmt.Sprintf("Context is small (%d messages) — nothing to compact.", beforeCount)}
423→	}
424→
425→	// Build a simple summary from the kept messages' context
426→	summary := fmt.Sprintf("Previous conversation had %d messages covering %d turns.", beforeCount, m.turns)
427→	before, after := m.session.Compact(summary, compactKeepRecent)
428→
429→	beforePct := m.contextPct
430→	// Estimate new context %: rough proportional reduction
431→	if before > 0 {
432→		m.contextPct = m.contextPct * float64(after) / float64(before)
433→	}
434→
435→	return CommandResult{
436→		Message: fmt.Sprintf(
437→			"Compacted: %d → %d messages (%.0f%% → ~%.0f%% context)",
438→			before, after, beforePct, m.contextPct,
439→		),
440→	}
441→}
442→
443→// commandResultMsg wraps a CommandResult for the Bubble Tea message loop.
444→type commandResultMsg CommandResult
445→
446→// runCommand returns a tea.Cmd that executes a slash command and sends the result.
447→func (m *appModel) runCommand(cmd *Command) tea.Cmd {
448→	result := m.executeCommand(cmd)
449→	return func() tea.Msg {
450→		return commandResultMsg(result)
451→	}
452→}
453→
454→// ParseShellEscape checks if input starts with ! and returns the command.
455→// Returns ("", false) if not a shell escape.
456→// Returns ("", true) for bare "!" with no command.
457→func ParseShellEscape(input string) (string, bool) {
458→	input = strings.TrimSpace(input)
459→	if !strings.HasPrefix(input, "!") {
460→		return "", false
461→	}
462→	cmd := strings.TrimSpace(input[1:])
463→	return cmd, true
464→}
465→
466→const (
467→	shellTimeout    = 30 * time.Second
468→	shellMaxOutput  = 10240 // 10KB
469→)
470→
471→// shellResultMsg carries the result of a shell escape command.
472→type shellResultMsg struct {
473→	Command  string
474→	Output   string
475→	ExitCode int
476→	Err      error
477→	TimedOut bool
478→}
479→
480→// runShellCommand executes a shell command and returns a tea.Cmd that sends the result.
481→func (m *appModel) runShellCommand(command string) tea.Cmd {
482→	workDir := m.workDir
483→	return func() tea.Msg {
484→		ctx, cancel := context.WithTimeout(context.Background(), shellTimeout)
485→		defer cancel()
486→
487→		cmd := exec.CommandContext(ctx, "bash", "-c", command)
488→		cmd.Dir = workDir
489→		out, err := cmd.CombinedOutput()
490→
491→		output := string(out)
492→		if len(output) > shellMaxOutput {
493→			output = output[:shellMaxOutput] + "\n... (truncated)"
494→		}
495→
496→		exitCode := 0
497→		timedOut := ctx.Err() == context.DeadlineExceeded
498→		if err != nil {
499→			if exitErr, ok := err.(*exec.ExitError); ok {
500→				exitCode = exitErr.ExitCode()
501→			} else if !timedOut {
502→				return shellResultMsg{Command: command, Err: err}
503→			}
504→		}
505→
506→		return shellResultMsg{
507→			Command:  command,
508→			Output:   output,
509→			ExitCode: exitCode,
510→			TimedOut: timedOut,
511→		}
512→	}
513→}
